const request = $json ?? {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const getHeader = (name) => { const lower = String(name).toLowerCase(); const key = Object.keys(headers).find((item) => String(item).toLowerCase() === lower); return key ? headers[key] : undefined; };
const expectedToken = String($env.N8N_WORKFLOWS_TOKEN || '').trim();
let providedToken = String(getHeader('authorization') || getHeader('x-aiops-workflows-token') || '').trim().replace(/^bearer\s+/i, '').trim();
if (!expectedToken) return [{ json: { ok: false, status_code: 500, error: 'N8N_WORKFLOWS_TOKEN is not set' } }];
if (providedToken !== expectedToken) return [{ json: { ok: false, status_code: 401, error: 'invalid workflows token' } }];
const rawBase = String($env.N8N_WEBHOOK_BASE_URL || ($env.N8N_PUBLIC_API_BASE_URL ? `${String($env.N8N_PUBLIC_API_BASE_URL).replace(/\/+$/, '')}/webhook` : '')).replace(/\/+$/, '');
if (!rawBase) return [{ json: { ok: false, status_code: 500, error: 'webhook base URL is not configured' } }];
try {
  const response = await this.helpers.httpRequest({ method: 'POST', url: `${rawBase}/sulu/configuration-recovery`, json: true, body: { realm: String($env.N8N_REALM || $env.N8N_ENV_REALM || 'aiops'), desired_state: 'up', dry_run: true, change_id: 'OQ-S2-SELFTEST', issue_url: 'https://gitlab.invalid/issues/1', mr_url: 'https://gitlab.invalid/merge_requests/1', correlation_id: 'oq-s2-selftest' }, timeout: 30000 });
  const tests = Array.isArray(response?.assessment?.tests) ? response.assessment.tests : [];
  const passed = response?.ok === true && response?.workflow_id === 'wf.sulu_configuration_recovery' && response?.dry_run === true && response?.simulated === true && response?.applied === false && response?.verification?.status === 'passed' && tests.every((test) => test?.status === 'passed');
  return [{ json: { ok: passed, status_code: passed ? 200 : 500, target_response: response, error: passed ? null : 'target workflow assertions failed' } }];
} catch (error) { return [{ json: { ok: false, status_code: 500, error: error?.message ? String(error.message) : String(error) } }]; }
